 * touch_diag.c — 触摸屏诊断（带 I2C 超时保护）
 *
 * 用法：nsh> touch_diag
 *
 * Contest 2026 Team 307
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <nuttx/i2c/i2c_master.h>
#include <pthread.h>

#define FT6146_ADDR     0x38
#define FT6146_REG_ID_H 0xA3
#define FT6146_REG_ID_L 0x9F
#define FT6146_REG_TD   0x02
#define I2C_TIMEOUT_MS  2000

/****************************************************************************
 * I2C 超时封装
 ****************************************************************************/

struct i2c_task
{
  int fd;
  uint8_t reg;
  uint8_t *buf;
  int len;
  int result;
};

static void *i2c_read_thread(void *arg)
{
  struct i2c_task *t = (struct i2c_task *)arg;
  struct i2c_msg_s msgs[2];
  struct i2c_transfer_s xfer;

  msgs[0].addr   = FT6146_ADDR;
  msgs[0].flags  = 0;
  msgs[0].buffer = &t->reg;
  msgs[0].length = 1;

  msgs[1].addr   = FT6146_ADDR;
  msgs[1].flags  = I2C_M_READ;
  msgs[1].buffer = t->buf;
  msgs[1].length = t->len;

  xfer.msgv = msgs;
  xfer.msgc = 2;

  t->result = ioctl(t->fd, I2CIOC_TRANSFER, (unsigned long)&xfer);
  return NULL;
}

static int i2c_read_with_timeout(int fd, uint8_t reg, uint8_t *buf, int len)
{
  struct i2c_task task = { fd, reg, buf, len, -1 };
  pthread_t tid;
  struct timespec ts;

  pthread_create(&tid, NULL, i2c_read_thread, &task);

  clock_gettime(CLOCK_REALTIME, &ts);
  ts.tv_sec  += I2C_TIMEOUT_MS / 1000;
  ts.tv_nsec += (I2C_TIMEOUT_MS % 1000) * 1000000;
  if (ts.tv_nsec >= 1000000000)
    {
      ts.tv_sec++;
      ts.tv_nsec -= 1000000000;
    }

  int ret = pthread_timedjoin_np(tid, NULL, &ts);
  if (ret != 0)
    {
      printf("  [WARN] I2C timeout (%dms), bus may be stuck\n",
             I2C_TIMEOUT_MS);
      pthread_cancel(tid);
      return -ETIMEDOUT;
    }

  return task.result;
}

/****************************************************************************
 * 主函数
 ****************************************************************************/

int main(int argc, char *argv[])
{
  uint8_t buf[8];
  int fd, ret;

  printf("=== Touch Diagnostic (timeout=%dms) ===\n\n", I2C_TIMEOUT_MS);

  fd = open("/dev/i2c0", O_RDWR);
  if (fd < 0)
    {
      printf("[FAIL] open /dev/i2c0 failed: %d\n", fd);
      return -1;
    }

  printf("[OK] /dev/i2c0 opened\n");

  /* Test 1: I2C scan with timeout */

  printf("\n--- Test 1: I2C scan at 0x%02X ---\n", FT6146_ADDR);
  ret = i2c_read_with_timeout(fd, 0x00, buf, 1);
  if (ret == -ETIMEDOUT)
    {
      printf("[FAIL] I2C timeout — bus stuck\n");
      printf("  → Check: power supply, reset pin, I2C wiring\n");
    }
  else if (ret < 0)
    {
      printf("[FAIL] No ACK at 0x%02X (ret=%d)\n", FT6146_ADDR, ret);
    }
  else
    {
      printf("[OK] ACK at 0x%02X\n", FT6146_ADDR);
    }

  /* Test 2: Read FT6146 ID */

  printf("\n--- Test 2: Read FT6146 ID ---\n");
  ret = i2c_read_with_timeout(fd, FT6146_REG_ID_H, buf, 1);
  if (ret == -ETIMEDOUT)
    printf("[FAIL] ID_H timeout\n");
  else if (ret < 0)
    printf("[FAIL] ID_H read failed: %d\n", ret);
  else
    printf("[OK] ID_H = 0x%02X\n", buf[0]);

  ret = i2c_read_with_timeout(fd, FT6146_REG_ID_L, buf, 1);
  if (ret == -ETIMEDOUT)
    printf("[FAIL] ID_L timeout\n");
  else if (ret < 0)
    printf("[FAIL] ID_L read failed: %d\n", ret);
  else
    printf("[OK] ID_L = 0x%02X\n", buf[0]);

  /* Test 3: Read touch data */

  printf("\n--- Test 3: Read touch data ---\n");
  ret = i2c_read_with_timeout(fd, FT6146_REG_TD, buf, 5);
  if (ret == -ETIMEDOUT)
    printf("[FAIL] Touch data timeout\n");
  else if (ret < 0)
    printf("[FAIL] Touch data read failed: %d\n", ret);
  else
    {
      printf("[OK] Data: %02X %02X %02X %02X %02X\n",
             buf[0], buf[1], buf[2], buf[3], buf[4]);
      int n = buf[0] & 0x0F;
      if (n > 0)
        {
          int x = ((buf[1] & 0x0F) << 8) | buf[2];
          int y = ((buf[3] & 0x0F) << 8) | buf[4];
          printf("  → Touch: (%d, %d)\n", x, y);
        }
      else
        printf("  → No touch\n");
    }

  /* Test 4: Continuous scan */

  printf("\n--- Test 4: Continuous scan (5s) ---\n");
  for (int i = 0; i < 5; i++)
    {
      ret = i2c_read_with_timeout(fd, FT6146_REG_TD, buf, 5);
      if (ret == -ETIMEDOUT)
        printf("[%d] timeout\n", i);
      else if (ret < 0)
        printf("[%d] fail(%d)\n", i, ret);
      else
        {
          int n = buf[0] & 0x0F;
          if (n > 0)
            {
              int x = ((buf[1] & 0x0F) << 8) | buf[2];
              int y = ((buf[3] & 0x0F) << 8) | buf[4];
              printf("[%d] Touch(%d,%d)\n", i, x, y);
            }
          else
            printf("[%d] OK no touch\n", i);
        }
      sleep(1);
    }

  close(fd);
  printf("\n=== Done ===\n");
  return 0;
}
