98	
99	int main(int argc, FAR char *argv[])
100	{
101	  lv_nuttx_dsc_t    dsc;
102	  lv_nuttx_result_t result;
103	  uint32_t          idle;
104	
105	  printf("=== Day 2 UI Demo (Team 307) ===\n");
106	
107	  /* 检查 LVGL 是否已初始化 */
108	
109	  if (lv_is_initialized())
110	    {
111	      printf("ERROR: LVGL already initialized by another app.\n");
112	      printf("Please stop the other app first, or disable CONFIG_QUICKAPP.\n");
113	      return -1;
114	    }
115	
116	  /* LVGL 初始化 */
117	
118	  lv_init();
119	  lv_nuttx_dsc_init(&dsc);
120	
121	  dsc.fb_path    = "/dev/lcd0";
122	  dsc.input_path = "/dev/input0";
123	
124	  lv_nuttx_init(&dsc, &result);
125	
126	  if (result.disp == NULL)
127	    {
128	      printf("ERROR: display init failed\n");
129	      return -1;
130	    }
131	
132	  printf("Display: %dx%d\n", SCREEN_WIDTH, SCREEN_HEIGHT);
133	
134	  /* 初始化中文字体 */
135	
136	  if (ui_font_init() < 0)
137	    {
138	      printf("WARNING: Chinese font init failed, some text may not display.\n");
139	    }
140	
141	  /* 创建主界面 */
142	
143	  create_main_ui();
144	
145	  printf("UI ready. Main loop running.\n");
146	
147	  /* 主循环 */
148	
149	  while (1)
150	    {
151	      idle = lv_timer_handler();
152	      idle = idle ? idle : 1;
153	      usleep(idle * 1000);
154	    }
155	
156	  /* 清理（实际上不会执行到） */
157	
158	  ui_font_deinit();
159	  lv_nuttx_deinit(&result);
160	  lv_deinit();
161	
162	  return 0;
163	}
