1	/****************************************************************************
2	 * popup.c — 弹窗组件
3	 *
4	 * 结构：半透明遮罩 + 白色卡片 + 标题 + 内容 + 确认按钮
5	 * 支持：点击按钮关闭，回调通知
6	 *
7	 * Contest 2026 Team 307
8	 ****************************************************************************/
9	
10	#include "ui_common.h"
11	#include "popup.h"
12	
13	/****************************************************************************
14	 * 弹窗上下文
15	 ****************************************************************************/
16	
17	struct popup_ctx
18	{
19	  popup_cb_t  cb;
20	  void       *user_data;
21	  lv_obj_t   *popup;      /* 最外层遮罩 */
22	};
23	
24	/****************************************************************************
25	 * 按钮回调
26	 ****************************************************************************/
27	
28	static void btn_confirm_cb(lv_event_t *e)
29	{
30	  struct popup_ctx *ctx = (struct popup_ctx *)lv_event_get_user_data(e);
31	  if (ctx->cb)
32	    ctx->cb(ctx->user_data);
33	  popup_close(ctx->popup);
34	  lv_free(ctx);
35	}
36	
37	static void overlay_click_cb(lv_event_t *e)
38	{
39	  /* 点击遮罩空白区域也关闭 */
40	
41	  struct popup_ctx *ctx = (struct popup_ctx *)lv_event_get_user_data(e);
42	  popup_close(ctx->popup);
43	  lv_free(ctx);
44	}
45	
46	/****************************************************************************
47	 * 公开接口
48	 ****************************************************************************/
49	
50	lv_obj_t *popup_create(lv_obj_t *parent, const char *title,
51	                       const char *content, const char *btn_text,
52	                       popup_cb_t cb, void *user_data)
53	{
54	  struct popup_ctx *ctx = lv_malloc(sizeof(struct popup_ctx));
55	  ctx->cb       = cb;
56	  ctx->user_data = user_data;
57	
58	  /* 半透明遮罩层 */
59	
60	  lv_obj_t *overlay = lv_obj_create(parent);
61	  lv_obj_set_size(overlay, SCREEN_WIDTH, SCREEN_HEIGHT);
62	  lv_obj_set_style_bg_color(overlay, lv_color_hex(0x000000), 0);
63	  lv_obj_set_style_bg_opa(overlay, LV_OPA_60, 0);
64	  lv_obj_set_style_border_width(overlay, 0, 0);
65	  lv_obj_set_style_radius(overlay, 0, 0);
66	  lv_obj_remove_flag(overlay, LV_OBJ_FLAG_SCROLLABLE);
67	  lv_obj_align(overlay, LV_ALIGN_TOP_LEFT, 0, 0);
68	
69	  ctx->popup = overlay;
70	
71	  /* 点击遮罩关闭 */
72	
73	  lv_obj_add_event_cb(overlay, overlay_click_cb, LV_EVENT_CLICKED, ctx);
74	
75	  /* 白色卡片 */
76	
77	  lv_obj_t *card = lv_obj_create(overlay);
78	  lv_obj_set_size(card, 320, 220);
79	  lv_obj_set_style_bg_color(card, COLOR_BG_CARD, 0);
80	  lv_obj_set_style_bg_opa(card, LV_OPA_COVER, 0);
81	  lv_obj_set_style_radius(card, 16, 0);
82	  lv_obj_set_style_border_width(card, 0, 0);
83	  lv_obj_set_style_pad_all(card, 20, 0);
84	  lv_obj_remove_flag(card, LV_OBJ_FLAG_SCROLLABLE);
85	  lv_obj_center(card);
86	
87	  /* Flex 布局 */
88	
89	  lv_obj_set_flex_flow(card, LV_FLEX_FLOW_COLUMN);
90	  lv_obj_set_flex_align(card, LV_FLEX_ALIGN_CENTER,
91	                         LV_FLEX_ALIGN_CENTER,
92	                         LV_FLEX_ALIGN_CENTER);
93	  lv_obj_set_style_pad_row(card, 12, 0);
94	
95	  /* 阻止卡片点击事件冒泡到遮罩 */
96	
97	  lv_obj_add_flag(card, LV_OBJ_FLAG_CLICKABLE);
98	  lv_obj_add_event_cb(card, NULL, LV_EVENT_CLICKED, NULL);
99	
100	  /* 标题 */
101	
102	  ui_create_label(card, title, FONT_LARGE, COLOR_TEXT_WHITE);
103	
104	  /* 分隔线 */
105	
106	  lv_obj_t *line = lv_obj_create(card);
107	  lv_obj_set_size(line, 260, 1);
108	  lv_obj_set_style_bg_color(line, COLOR_TEXT_GRAY, 0);
109	  lv_obj_set_style_bg_opa(line, LV_OPA_30, 0);
110	  lv_obj_set_style_border_width(line, 0, 0);
111	
112	  /* 内容 */
113	
114	  lv_obj_t *content_label = ui_create_label(card, content,
115	                                            FONT_MEDIUM, COLOR_TEXT_GRAY);
116	  lv_obj_set_width(content_label, 260);
117	  lv_label_set_long_mode(content_label, LV_LABEL_LONG_WRAP);
118	  lv_obj_set_style_text_align(content_label, LV_TEXT_ALIGN_CENTER, 0);
119	
120	  /* 确认按钮 */
121	
122	  const char *text = btn_text ? btn_text : "确认";
123	  lv_obj_t *btn = ui_create_button(card, 200, 44, text, btn_confirm_cb);
124	  lv_obj_add_event_cb(btn, btn_confirm_cb, LV_EVENT_CLICKED, ctx);
125	
126	  return overlay;
127	}
128	
129	void popup_close(lv_obj_t *popup)
130	{
131	  if (popup)
132	    lv_obj_del(popup);
133	}
